<template>
  <el-container>
    <el-header width="auto" style="margin-top: 4px">
      <AsideVue/>
    </el-header>

    <el-main class="main-ctx">
      <div class="analysis-wrapper">

        <!-- 第一列：原始视频 -->
        <el-card class="col-card">
          <template #header>
            <div class="card-header-row">
              <el-button type="text" @click="goBack">
                <el-icon><ArrowLeftBold/></el-icon> 返回
              </el-button>
              <el-tag type="primary" style="padding: 8px 16px; font-size: 13px">学生视角</el-tag>
            </div>
          </template>
          <video class="fit-video" :src="studentVideoUrl" muted preload="auto" controls></video>
          <div style="margin-top: 14px; text-align: center">
            <el-button type="primary" size="large" :loading="loading"
                       @click="startAnalysis" style="width: 100%; font-size: 14px">
              <el-icon style="margin-right: 6px"><VideoPlay/></el-icon>
              {{ loading ? '正在分析中...' : '开始人脸表情分析' }}
            </el-button>
          </div>
        </el-card>

        <!-- 第二列：分析数据 -->
        <el-card class="col-card" v-loading="loading" element-loading-text="正在进行表情识别，请耐心等待...">
          <template #header>
            <span style="font-weight: 600; font-size: 15px">分析结果</span>
          </template>

          <el-empty v-if="!analysisResult && !loading"
                    description="点击左侧【开始人脸表情分析】按钮开始分析" />

          <div v-if="analysisResult">
            <!-- 专注度评分 -->
            <div class="section-title">专注度评分</div>
            <div class="score-block">
              <el-progress
                type="dashboard"
                :percentage="analysisResult.attention_score"
                :color="scoreColor"
                :stroke-width="14"
                :width="130"
              >
                <template #default>
                  <div class="score-inner">
                    <div class="score-num">{{ analysisResult.attention_score }}</div>
                    <div class="score-unit">分</div>
                  </div>
                </template>
              </el-progress>
              <div class="score-info">
                <div class="score-level" :style="{color: scoreColor}">{{ scoreLevel }}</div>
                <div class="score-comment">{{ scoreComment }}</div>
              </div>
            </div>

            <el-divider/>

            <!-- 表情统计 -->
            <div class="section-title">表情统计</div>
            <div class="emotion-bars">
              <div class="emotion-bar-item"
                   v-for="(count, emotion) in filteredEmotionCount"
                   :key="emotion">
                <div class="emotion-label">{{ emotion }}</div>
                <el-progress
                  :percentage="getEmotionPercent(count)"
                  :color="emotionColors[emotion]"
                  :stroke-width="16"
                  style="flex: 1"
                />
                <div class="emotion-count">{{ count }}帧</div>
              </div>
            </div>
          </div>
        </el-card>

        <!-- 第三列：识别结果视频 + 报告按钮 -->
        <el-card class="col-card">
          <template #header>
            <span style="font-weight: 600; font-size: 15px">识别结果视频</span>
          </template>

          <el-empty v-if="!resultVideoUrl && !loading" description="完成分析后展示识别视频" />

          <div v-if="resultVideoUrl">
            <!-- 视频操作按钮（用原生 a 标签，el-button 不支持 href） -->
            <div style="margin: 10px 0; display: flex; gap: 8px;">
              <a :href="resultVideoUrl" target="_blank">
                <el-button type="primary">打开视频</el-button>
              </a>
              <a :href="resultVideoUrl" download>
                <el-button type="success">下载视频</el-button>
              </a>
            </div>

            <!-- 识别结果视频：直接用 :src 绑定，避免 source 标签不更新的 bug -->
            <video
              ref="resultVideo"
              :src="resultVideoUrl"
              width="100%"
              height="300"
              controls
              style="display:block; background:#000; border-radius:4px;"
              @error="handleVideoError"
              @loadedmetadata="handleVideoLoaded"
            ></video>
            <p v-if="videoError" style="color:#F56C6C; font-size:12px; margin-top:4px;">
              视频加载失败：{{ videoError }}
            </p>
          </div>

          <div v-if="analysisResult" style="margin-top: 16px; display: flex; flex-direction: column; gap: 10px">
            <el-button type="success" size="large"
                       :loading="reportLoading"
                       @click="generateReport"
                       style="width: 100%; font-size: 14px">
              <el-icon style="margin-right: 6px"><Document/></el-icon>
              {{ reportLoading ? '正在生成报告...' : '生成分析报告' }}
            </el-button>
            <a v-if="reportUrl" :href="reportUrl" target="_blank" download style="width: 100%">
              <el-button type="primary" plain size="large" style="width: 100%; font-size: 14px">
                <el-icon style="margin-right: 6px"><Download/></el-icon>
                下载PDF报告
              </el-button>
            </a>
            <el-button type="warning" size="large"
                       :loading="learningReportLoading"
                       @click="generateLearningReport"
                       style="width: 100%; font-size: 14px">
              <el-icon style="margin-right: 6px"><Document/></el-icon>
              {{ learningReportLoading ? '正在生成学习报告...' : '生成学习报告' }}
            </el-button>
            <a v-if="learningReportUrl" :href="learningReportUrl" target="_blank" download style="width: 100%">
              <el-button type="primary" plain size="large" style="width: 100%; font-size: 14px">
                <el-icon style="margin-right: 6px"><Download/></el-icon>
                下载学习报告
              </el-button>
            </a>
          </div>
        </el-card>

      </div>
    </el-main>
  </el-container>
</template>

<script>
import "@/assets/css/app.css";
import axios from 'axios';
import AsideVue from "@/components/AsideVue";
import { ArrowLeftBold, VideoPlay, Document, Download } from "@element-plus/icons-vue";

export default {
  name: "VideoAnalysis",
  components: {
    AsideVue,
    ArrowLeftBold,
    VideoPlay,
    Document,
    Download,
  },
  data() {
    return {
      studentVideoUrl: '',
      resultVideoUrl: '',
      loading: false,
      reportLoading: false,
      learningReportLoading: false,
      reportUrl: '',
      learningReportUrl: '',
      analysisResult: null,
      videoError: '',
      emotionColors: {
        '专注': '#67C23A',
        '开心': '#409EFF',
        '惊讶': '#E6A23C',
        '愤怒': '#F56C6C',
      },
    };
  },

  computed: {
    scoreColor() {
      const s = this.analysisResult?.attention_score || 0;
      if (s >= 70) return '#67C23A';
      if (s >= 40) return '#E6A23C';
      return '#F56C6C';
    },
    scoreLevel() {
      const s = this.analysisResult?.attention_score || 0;
      if (s >= 70) return '优秀';
      if (s >= 40) return '一般';
      return '较低';
    },
    scoreComment() {
      const s = this.analysisResult?.attention_score || 0;
      if (s >= 70) return '课堂专注度良好，学习状态积极！';
      if (s >= 40) return '专注度中等，可适当引导提升。';
      return '专注度偏低，建议教师加强互动。';
    },
    filteredEmotionCount() {
      if (!this.analysisResult?.emotion_count) return {};
      const ec = this.analysisResult.emotion_count;
      const result = {};
      ['专注', '开心', '惊讶', '愤怒'].forEach(k => {
        if (ec[k] !== undefined) result[k] = ec[k];
      });
      return result;
    },
  },

  watch: {
    resultVideoUrl(newUrl) {
      if (newUrl && this.$refs.resultVideo) {
        this.$nextTick(() => {
          this.$refs.resultVideo.load();
        });
      }
    },
  },

  mounted() {
    this.studentVideoUrl = this.$route.query.video || '';
    if (!this.studentVideoUrl) {
      this.$message.warning('未获取到视频地址，请返回重新选择');
    }
  },

  methods: {
    goBack() {
      this.$router.go(-1);
    },

    getEmotionPercent(count) {
      if (!this.analysisResult) return 0;
      const ec = this.analysisResult.emotion_count;
      const noFace = ec['无人脸'] || 0;
      const faceFrames = this.analysisResult.total_frames - noFace;
      if (faceFrames === 0) return 0;
      return Math.round((count / faceFrames) * 100);
    },

    async startAnalysis() {
      if (!this.studentVideoUrl) {
        this.$message.error('视频地址为空，请返回重新选择');
        return;
      }
      this.loading = true;
      this.analysisResult = null;
      this.resultVideoUrl = '';
      this.reportUrl = '';
      this.learningReportUrl = '';
      const form = new FormData();
      form.append('video', this.studentVideoUrl);
      try {
        console.log('开始分析，视频URL:', this.studentVideoUrl);
        const response = await axios.post('/api/expressionRecognition', form);
        console.log('分析完成，响应数据:', response.data);
        const data = response.data;
        this.resultVideoUrl = data.videoUrl || '';
        this.analysisResult = data.stats || null;
        console.log('设置resultVideoUrl:', this.resultVideoUrl);
        console.log('设置analysisResult:', this.analysisResult);
        // 测试视频URL是否可访问
        try {
          const videoResponse = await axios.head(this.resultVideoUrl);
          console.log('视频URL访问成功:', videoResponse.status);
          console.log('视频URL响应头:', videoResponse.headers);
        } catch (videoError) {
          console.error('视频URL访问失败:', videoError);
        }
        this.$message.success('表情识别完成！');
        // 将分析结果存入 localStorage，WorkStation 可读取触发AI建议
        try {
          localStorage.setItem('lastAnalysisStats', JSON.stringify(data.stats));
          localStorage.setItem('lastAnalysisTime', Date.now().toString());
        } catch(e) {
          console.error('存储localStorage失败:', e);
        }
      } catch (error) {
        console.error('表情识别失败', error);
        this.$message.error('分析失败，请检查后端服务是否正常运行');
      } finally {
        this.loading = false;
      }
    },

    handleVideoError(event) {
      console.error('视频加载错误:', event);
      if (event.target && event.target.error) {
        console.error('错误代码:', event.target.error.code);
        this.videoError = event.target.error.message || '加载失败';
      } else {
        this.videoError = '未知错误';
      }
    },

    handleVideoLoaded(event) {
      console.log('视频加载成功，时长:', event.target.duration);
      this.videoError = '';
    },

    async generateReport() {
      if (!this.analysisResult) {
        this.$message.warning('请先完成表情分析再生成报告');
        return;
      }
      this.reportLoading = true;
      const videoName = this.studentVideoUrl.split('/').pop() || '未知视频';
      try {
        const response = await axios.post('/api/generateReport', {
          emotion_count: this.analysisResult.emotion_count,
          attention_score: this.analysisResult.attention_score,
          total_frames: this.analysisResult.total_frames,
          video_name: videoName,
        });
        this.reportUrl = response.data.reportUrl || '';
        this.$message.success('报告生成成功，点击下载！');
      } catch (error) {
        console.error('生成报告失败', error);
        this.$message.error('报告生成失败，请检查后端服务');
      } finally {
        this.reportLoading = false;
      }
    },

    async generateLearningReport() {
      if (!this.analysisResult) {
        this.$message.warning('请先完成人脸表情分析，再生成学习报告');
        return;
      }
      this.learningReportLoading = true;
      const videoName = this.studentVideoUrl.split('/').pop() || '未知视频';
      try {
        const response = await axios.post('/api/generateLearningReport', {
          emotion_count: this.analysisResult.emotion_count,
          attention_score: this.analysisResult.attention_score,
          total_frames: this.analysisResult.total_frames,
          video_name: videoName,
        });
        this.learningReportUrl = response.data.reportUrl || '';
        if (response.data.deeptutorFound === false) {
          this.$message.warning('学习报告已生成，但未读取到 DeepTutor 最新回答');
        } else {
          this.$message.success('学习报告生成成功，点击下方按钮下载');
        }
      } catch (error) {
        console.error('生成学习报告失败', error);
        this.$message.error('学习报告生成失败，请检查后端服务');
      } finally {
        this.learningReportLoading = false;
      }
    },
  },
};
</script>

